        for (T x : arr)
            System.out.print(x + " ");
        System.out.println();
    }

    public static void main(String[] args) {
        Integer[] ints = {38, 27, 43, 10};
        new Sorter<>(new MergeSort<>(Comparator.naturalOrder())).sort(ints);
        printArray(ints);

